import React, { useEffect, useState, useRef } from "react";
import { GoogleMap, Marker, LoadScript, DirectionsRenderer } from "@react-google-maps/api";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const containerStyle = {
  width: "100%",
  height: "600px",
};

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function DeliveryTrackingPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [driverLocation, setDriverLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [deliveryLocation, setDeliveryLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);

  const mapRef = useRef<google.maps.Map>();

  // Function to geocode an address
  const geocodeAddress = async (address: string): Promise<{ lat: number; lng: number } | null> => {
    try {
      const response = await axios.get(
        `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${process.env.REACT_APP_GOOGLE_MAPS_API_KEY}`
      );
      if (response.data.status === "OK") {
        const { lat, lng } = response.data.results[0].geometry.location;
        return { lat, lng };
      } else {
        console.error("Geocoding failed:", response.data.status);
        return null;
      }
    } catch (error) {
      console.error("Geocoding error:", error);
      return null;
    }
  };

  // Fetch delivery and driver details
  useEffect(() => {
    if (!id) return;

    const fetchData = async () => {
      try {
        const deliveryRes = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        const delivery = deliveryRes.data;

        // Delivery location (already geocoded in your backend)
        setDeliveryLocation(delivery.location);

        // Fetch driver details
        const driverId = delivery.driverId;
        const driverRes = await axios.get(`${API_BASE_URL}/api/drivers/${driverId}`);
        const driver = driverRes.data;

        // Geocode driver's address
        if (driver.address) {
          const driverCoords = await geocodeAddress(driver.address);
          if (driverCoords) {
            setDriverLocation(driverCoords);
          }
        }
      } catch (error) {
        console.error("Error fetching delivery or driver:", error);
      }
    };

    fetchData();
  }, [id]);

  // Calculate route from driver to delivery
  useEffect(() => {
    if (!driverLocation || !deliveryLocation) return;

    const directionsService = new google.maps.DirectionsService();
    directionsService.route(
      {
        origin: driverLocation,
        destination: deliveryLocation,
        travelMode: google.maps.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status === window.google.maps.DirectionsStatus.OK && result) {
          setDirections(result);
        } else {
          console.error("Directions request failed:", status);
        }
      }
    );
  }, [driverLocation, deliveryLocation]);

  return (
    <div style={{ padding: "20px" }}>
      <h2>🚚 Delivery Tracking</h2>

      <LoadScript googleMapsApiKey={process.env.REACT_APP_GOOGLE_MAPS_API_KEY!}>
        <GoogleMap
          mapContainerStyle={containerStyle}
          center={driverLocation || deliveryLocation || { lat: 6.9271, lng: 79.8612 }}
          zoom={13}
          onLoad={(map) => {
            mapRef.current = map;
          }}
        >
          {/* Driver Marker */}
          {driverLocation && (
            <Marker
              position={driverLocation}
              label={{ text: "Driver", color: "white", fontWeight: "bold" }}
              icon={{
                url: "http://maps.google.com/mapfiles/ms/icons/blue-dot.png",
              }}
            />
          )}

          {/* Delivery Marker */}
          {deliveryLocation && (
            <Marker
              position={deliveryLocation}
              label={{ text: "Delivery", color: "white", fontWeight: "bold" }}
              icon={{
                url: "http://maps.google.com/mapfiles/ms/icons/red-dot.png",
              }}
            />
          )}

          {/* Route */}
          {directions && (
            <DirectionsRenderer directions={directions} />
          )}
        </GoogleMap>
      </LoadScript>

      <button
        onClick={() => navigate("/")}
        style={{
          marginTop: "20px",
          padding: "10px 20px",
          backgroundColor: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
          cursor: "pointer",
        }}
      >
        ← Back to Dashboard
      </button>
    </div>
  );
}
